+                .sorted(Map.Entry.comparingByKey(Comparator.comparing(Path::toString)))
+                .forEach(entry -> result.put(entry.getKey(), entry.getValue()));
+        return result;
+    }
+
+    private static Path createStagingRoot() {
+        try {
+            return Files.createTempDirectory("jte-jsp-migration-");
+        } catch (IOException e) {
+            throw new UncheckedIOException(e);
+        }
+    }
+
+    private static Path copyToStaging(Path normalizedJspRoot, Path resourceBasePath, Path stagingRoot) throws IOException {
+        Path relativeRoot = resourceBasePath.equals(normalizedJspRoot)
+                ? Paths.get("")
+                : resourceBasePath.relativize(normalizedJspRoot);
+        if (relativeRoot.startsWith("..")) {
+            relativeRoot = Paths.get("");
+        }
+        Path stagingJspRoot = stagingRoot.resolve(relativeRoot).normalize();
+        try (Stream<Path> stream = Files.walk(normalizedJspRoot)) {
+            for (Iterator<Path> iterator = stream.iterator(); iterator.hasNext(); ) {
+                Path source = iterator.next();
+                Path destination = stagingJspRoot.resolve(normalizedJspRoot.relativize(source));
+                if (Files.isDirectory(source, LinkOption.NOFOLLOW_LINKS)) {
+                    Files.createDirectories(destination);
+                } else if (Files.isRegularFile(source, LinkOption.NOFOLLOW_LINKS)) {
+                    Files.createDirectories(destination.getParent());
+                    Files.copy(source, destination, StandardCopyOption.REPLACE_EXISTING);
+                }
+            }
+        }
+        return stagingJspRoot;
+    }
+
+    private static void writeVirtualFiles(Path stagingJspRoot, Path normalizedJspRoot,
+                                          Map<Path, String> conversionContents) throws IOException {
+        for (Map.Entry<Path, String> entry : conversionContents.entrySet()) {
+            writeStagingFile(stagingJspRoot, normalizedJspRoot, entry.getKey(), entry.getValue());
+        }
+    }
+
+    private static void writeStagingFile(Path stagingJspRoot, Path normalizedJspRoot,
+                                         Path sourcePath, String content) throws IOException {
+        Path stagingPath = stagingJspRoot.resolve(normalizedJspRoot.relativize(sourcePath)).normalize();
+        if (!stagingPath.startsWith(stagingJspRoot)) {
+            throw new IllegalArgumentException("Virtual JSP path is outside the JSP root: " + sourcePath);
+        }
+        Files.createDirectories(stagingPath.getParent());
+        Files.write(stagingPath, content.getBytes(StandardCharsets.UTF_8), StandardOpenOption.CREATE,
+                StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
+    }
+
+    private static void deleteStagingRoot(Path stagingRoot) {
+        if (stagingRoot == null) {
+            return;
+        }
+        try (Stream<Path> stream = Files.walk(stagingRoot)) {
+            List<Path> paths = new ArrayList<>();
+            stream.forEach(paths::add);
+            paths.sort(Comparator.comparingInt(Path::getNameCount).reversed());
+            for (Path path : paths) {
+                Files.deleteIfExists(path);
+            }
+        } catch (IOException ignored) {
+        }
+    }
+
+    private boolean isUsageFile(Path path) {
+        String fileName = path.getFileName().toString();
+        return fileName.endsWith(".jsp") || fileName.endsWith(".jsp.inc") || fileName.endsWith(".tag");
+    }
+
+    private static String toRelativeString(Path root, Path path) {
+        return root.relativize(path).toString().replace('\\', '/');
+    }
+
+    private static void ensureRealPathWithinRoot(Path path, Path root, String messagePrefix) {
+        try {
+            Path realRoot = root.toRealPath();
+            if (!path.toRealPath().startsWith(realRoot)) {
+                throw new IllegalArgumentException(messagePrefix + path);
+            }
+        } catch (IOException e) {
